package com.customcharge.dashboard.controller;import com.customcharge.dashboard.dto.EntityServiceChargeGroupDTO;import com.customcharge.dashboard.dto.ServiceChargeResponse;import com.customcharge.dashboard.dto.ServiceChargeUpdateRequest;import com.customcharge.dashboard.service.impl.ServiceChargeMappingService;import com.customcharge.dashboard.service.impl.ServiceChargeService;import io.swagger.v3.oas.annotations.Operation;import com.customcharge.persistencelayer.dto.response.MessageResponse;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.List;import java.util.Map;import java.util.UUID;@RestController@RequestMapping("/api/v1/service-charges")@RequiredArgsConstructorpublic class ServiceChargeController {    private final ServiceChargeService service;    private final ServiceChargeMappingService serviceChargeMappingService;    @PostMapping("/fetch")    @PreAuthorize("hasAuthority('AR_MANAGEMENT_VIEW')")    public List<ServiceChargeResponse> getCharges(            @RequestParam(required = false) String accountId,            @RequestParam String entityCode,            @RequestParam String chargeType) {        return service.getServiceCharges(accountId, entityCode, chargeType);    }    @GetMapping("/grouped-by-entity")    @PreAuthorize("hasAuthority('AR_MANAGEMENT_VIEW')")    @Operation(summary = "Mappings into entityCode (ECS/EC3), grouped by source fromEntity (map key = RUH, etc.)")    public Map<String, EntityServiceChargeGroupDTO> getEntityGroupedServiceCharges(            @RequestParam String entityCode,            @RequestParam String chargeType) {        return serviceChargeMappingService.getGroupedServiceCharges(entityCode, chargeType);    }    @PostMapping("/upsert")    @PreAuthorize("hasAuthority('AR_MANAGEMENT_EDIT')")    public MessageResponse update(@Valid @RequestBody List<@Valid ServiceChargeUpdateRequest> requests) {        return service.update(requests);    }    @DeleteMapping("/{id}")    @PreAuthorize("hasAuthority('AR_MANAGEMENT_DELETE')")    public MessageResponse delete(@PathVariable UUID id) {        return service.delete(id);    }}